import{_ as o,o as a,c as e,a3 as r}from"./chunks/framework.lx4Uzxpr.js";const h=JSON.parse('{"title":"正逆运动学：关节空间与笛卡尔空间的双向翻译","description":"正解是链式齐次变换的唯一解，逆解是非线性方程的多解难题；雅可比是两空间间的瞬时速度翻译官，奇异性即翻译官失聪的方向","frontmatter":{"title":"正逆运动学：关节空间与笛卡尔空间的双向翻译","date":"2026-10-24T00:00:00.000Z","tags":["机器人","数学","运动学"],"category":"notes","description":"正解是链式齐次变换的唯一解，逆解是非线性方程的多解难题；雅可比是两空间间的瞬时速度翻译官，奇异性即翻译官失聪的方向","sidebar":false},"headers":[],"relativePath":"notes/机器人/控制与运动生成/kinematics.md","filePath":"notes/机器人/控制与运动生成/kinematics.md"}'),s={name:"notes/机器人/控制与运动生成/kinematics.md"};function n(i,t,l,g,d,c){return a(),e("div",null,t[0]||(t[0]=[r('<h1 id="正逆运动学" tabindex="-1">正逆运动学 <a class="header-anchor" href="#正逆运动学" aria-label="Permalink to “正逆运动学”">​</a></h1><p><strong>一句话定义：运动学 = 关节空间（各关节角）与笛卡尔空间（末端位姿）之间的映射，不含力与质量——正解唯一，逆解多解且可能无解。</strong></p><h2 id="内核-为什么正逆解难度不对称" tabindex="-1">内核：为什么正逆解难度不对称 <a class="header-anchor" href="#内核-为什么正逆解难度不对称" aria-label="Permalink to “内核：为什么正逆解难度不对称”">​</a></h2><p><strong>正解（FK）</strong>：从基座到末端是一串连杆变换的连乘（<a href="/notes/机器人/数学基础/transform-homogeneous" class="term-link" title="位姿=坐标系间关系；齐次矩阵统一旋转与平移，左右乘各有确定含义">坐标变换与齐次矩阵</a>的链式法则），给定关节角，末端位姿<strong>必然唯一</strong>——机械结构替你保证。</p><p><strong>逆解（IK）</strong>：从末端位姿反解关节角 = 解一组非线性三角方程。三个结构性困难全都来自&quot;反着解&quot;：</p><ol><li><strong>多解</strong>：到达同一目标，肘上肘下、肩前肩后都行（n 自由度臂常有多组解）——解的选择要靠附加准则（离当前构型最近、避开障碍）；</li><li><strong>无解</strong>：目标超出工作空间或在奇异面另一侧——这是几何事实，不是算法失败；</li><li><strong>奇异附近病态</strong>：接近奇异位形时逆解的关节速度趋于无穷。</li></ol><p><strong>雅可比</strong>是两个空间之间的速度翻译官：$\\dot{x} = J(q),\\dot{q}$。它把&quot;每秒关节转多少&quot;翻译成&quot;末端每秒动多少&quot;。<strong>奇异性 = J 降秩 = 某些笛卡尔方向失去产生速度的能力</strong>（比如臂完全伸直时无法沿臂方向伸缩）。条件数 $\\kappa(J)$ 度量接近奇异的程度——轨迹规划要保证全程 $\\kappa$ 有界，这一条直接写进轨迹生成篇。</p><h2 id="规则与行为" tabindex="-1">规则与行为 <a class="header-anchor" href="#规则与行为" aria-label="Permalink to “规则与行为”">​</a></h2><p><strong>DH 参数</strong>：给连杆定四个参数（连杆长度 a、扭角 α、偏距 d、关节角 θ），使任何串联臂都能用统一的 4×4 变换表描述——FK 变成查表连乘。规则：<strong>DH 表是机械图纸的数字化，必须在装配后实测校验</strong>（零位对齐靠<a href="/notes/机器人/硬件与电子/encoders" class="term-link" title="位置反馈的真值来源：增量式数脉冲，绝对式读码">编码器</a>标定与限位）。</p><p><strong>速度层规则（J 的用法）</strong>：</p><ol><li><strong>微分运动</strong>：笛卡尔速度指令 → 关节速度，$\\dot{q} = J^{-1}\\dot{x}$——奇异附近 $J^{-1}$ 爆炸，实用中用阻尼最小二乘 $J^\\top(JJ^\\top + \\lambda I)^{-1}$，λ 换取速度上限的稳定；</li><li><strong>静力映射</strong>（对偶关系）：关节力矩 $\\tau = J^\\top F$——末端受力折算成各关节力矩，力控与重力补偿的基础；</li><li><strong>冗余臂</strong>：自由度 &gt; 6 时 $J$ 非方阵，用伪逆，解不唯一——<strong>零空间</strong>（$J\\dot{q}_0 = 0$ 的关节运动不改变末端位姿）用来同时完成避障/避奇异等次要目标。</li></ol><h2 id="抽象-数值-ik——把解析法统一成优化问题" tabindex="-1">抽象：数值 IK——把解析法统一成优化问题 <a class="header-anchor" href="#抽象-数值-ik——把解析法统一成优化问题" aria-label="Permalink to “抽象：数值 IK——把解析法统一成优化问题”">​</a></h2><p>解析 IK 只对少数构型（球腕六轴臂）存在。数值 IK 的抽象是：<strong>把&quot;找到关节角&quot;写成最小化问题</strong>（位置误差 + 姿态误差 + 避障/限位正则项），用雅可比迭代求解。它的好处是&quot;约束即正则项&quot;——任何附加要求都变成代价函数里的一项，不必发明新算法。运动学库（KDL、Pinocchio、TRAC-IK）全部是这个抽象的实现。上层（轨迹生成、动作库）只见 <code>solve_ik(target, seed)</code> 一个函数——<a href="/notes/机器人/规划与决策/hybrid-decision" class="term-link" title="FSM 管模式、行为树管行为、基元管动作的三层分工">混合决策架构</a>执行层里的每一次&quot;到某位姿&quot;，最终都落到这里。</p>',13)]))}const m=o(s,[["render",n]]);export{h as __pageData,m as default};
